<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>WastedToken Mint</title>
<style>
  body {
    margin: 0;
    padding: 0;
    background: #0d0d15;
    color: #e0e0e0;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    overflow-x: hidden;
  }
  .hero {
    height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    position: relative;
  }
  #coin-hero {
    width: 600px;
    height: 600px;
    border-radius: 50%;
    box-shadow: 0 0 80px rgba(255,215,0,0.3);
  }
  .about {
    padding: 60px 40px;
    max-width: 800px;
    margin: 0 auto;
    text-align: center;
  }
  .about h2 {
    font-size: 2.2em;
    margin-bottom: 20px;
    color: #fff;
  }
  .about p {
    line-height: 1.7;
    font-size: 1.05em;
    margin-bottom: 15px;
  }
  .collections {
    padding: 40px 20px;
    max-width: 1200px;
    margin: 0 auto;
  }
  .collections h2 {
    text-align: center;
    margin-bottom: 40px;
    font-size: 2em;
  }
  .grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
    gap: 30px;
  }
  .edition {
    background: #151520;
    border: 1px solid #2a2a3a;
    border-radius: 14px;
    padding: 20px;
    text-align: center;
    transition: transform 0.2s;
  }
  .edition:hover {
    transform: translateY(-4px);
  }
  .edition-canvas {
    width: 180px;
    height: 180px;
    margin: 0 auto 15px;
    border-radius: 50%;
  }
  .buy {
    background: #d4af37;
    color: #000;
    border: none;
    padding: 10px 24px;
    border-radius: 6px;
    font-weight: bold;
    cursor: pointer;
    font-size: 0.95em;
  }
  .buy:disabled {
    background: #444;
    color: #aaa;
    cursor: not-allowed;
  }
  .sold-out {
    border-color: #555;
    background: #1a1a2a;
  }
  .coming-soon {
    border-color: #1a1a3a;
    background: #131322;
  }
  .state-label {
    font-size: 0.85em;
    font-weight: bold;
    text-transform: uppercase;
    letter-spacing: 1px;
  }
  footer {
    text-align: center;
    padding: 30px;
    font-size: 0.9em;
    color: #777;
  }
</style>
</head>
<body>

<div class="hero">
  <canvas id="coin-hero"></canvas>
</div>

<section class="about">
  <h2>About WastedToken Mint</h2>
  <p>Welcome to <strong>WastedToken Mint</strong> — where blockchain dreams are forged into tangible art. We craft premium physical challenge coins for collectors, communities, and crypto enthusiasts who want something real to hold.</p>
  <p>Each coin in our collection is meticulously designed and produced using high-quality materials. From shimmering gold to rugged obsidian, every piece tells a story of value, rarity, and style.</p>
  <p>Our flagship coins are embedded with unique digital signatures verifiable on-chain, making them true fusion collectibles — part physical trophy, part NFT heirloom.</p>
  <p>Join thousands of collectors worldwide who’ve added our coins to their vaults. Whether you're here for the lore, the look, or the legacy — there's a coin here waiting for you.</p>
</section>

<section class="collections">
  <h2>Limited Edition Collections</h2>
  <div class="grid">
    <div class="edition" data-edition="bronze" data-state="available">
      <canvas class="edition-canvas"></canvas>
      <h3>Bronze Edition</h3>
      <p class="state-label">Available</p>
      <button class="buy">Add to cart</button>
    </div>
    <div class="edition" data-edition="silver" data-state="available">
      <canvas class="edition-canvas"></canvas>
      <h3>Silver Edition</h3>
      <p class="state-label">Available</p>
      <button class="buy">Add to cart</button>
    </div>
    <div class="edition sold-out" data-edition="gold" data-state="sold-out">
      <canvas class="edition-canvas"></canvas>
      <h3>Gold Edition</h3>
      <p class="state-label">SOLD OUT</p>
      <button class="buy" disabled>Sold Out</button>
    </div>
    <div class="edition coming-soon" data-edition="black" data-state="coming-soon">
      <canvas class="edition-canvas"></canvas>
      <h3>Obsidian Edition</h3>
      <p class="state-label">MINTING NEXT SEASON</p>
      <p>Available Spring 2025</p>
      <button class="buy" disabled>Minting Soon</button>
    </div>
  </div>
</section>

<footer>
  &copy; 2025 WastedToken Mint. All rights reserved.
</footer>

<script>
// ===== Hero Coin Animation =====
const canvas = document.getElementById('coin-hero');
const ctx = canvas.getContext('2d');
let animId = null;
let paused = false;

function resize() {
  const w = canvas.offsetWidth;
  const h = canvas.offsetHeight;
  if (canvas.width !== w || canvas.height !== h) {
    canvas.width = w;
    canvas.height = h;
  }
}
resize();

function drawCoin(ctx, t) {
  const cx = canvas.width / 2;
  const cy = canvas.height / 2;
  const radius = Math.min(cx, cy) * 0.75;

  // 3D rotation: vertical spin + horizontal flip
  const vertAngle = t * Math.PI * 2;      // rotate around Y
  const horizAngle = Math.sin(t * Math.PI) * 0.6; // flip around X

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.save();

  // Shadow
  ctx.beginPath();
  ctx.ellipse(cx, cy + radius * 0.1, radius * 0.4, radius * 0.12, 0, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(0,0,0,0.3)';
  ctx.fill();

  // Apply 3D-like transform manually via clipping + skew
  const scale = Math.abs(Math.cos(horizAngle)) * 0.3 + 0.7;
  ctx.translate(cx, cy);
  ctx.scale(scale, Math.cos(horizAngle) * 0.8 + 0.2);
  ctx.rotate(vertAngle);

  // Draw coin disc with metallic gradient
  const grad = ctx.createRadialGradient(0, -radius/2, radius*0.2, 0, 0, radius);
  grad.addColorStop(0, '#f0e68c');
  grad.addColorStop(0.5, '#d4af37');
  grad.addColorStop(1, '#8b7355');

  ctx.beginPath();
  ctx.arc(0, 0, radius, 0, Math.PI * 2);
  ctx.fillStyle = grad;
  ctx.fill();

  // Specular highlight
  ctx.beginPath();
  ctx.ellipse(0, -radius*0.3, radius*0.3, radius*0.1, Math.PI/4, 0, Math.PI*2);
  ctx.fillStyle = 'rgba(255,255,255,0.5)';
  ctx.fill();

  ctx.restore();

  // Reeded edge
  ctx.save();
  ctx.translate(cx, cy);
  ctx.lineWidth = radius * 0.04;
  ctx.strokeStyle = '#aaa';
  for (let i = 0; i < 60; i++) {
    ctx.beginPath();
    ctx.arc(0, 0, radius + radius*0.03, (i/60)*2*Math.PI, (i/60)*2*Math.PI + 0.05);
    ctx.stroke();
  }
  ctx.restore();

  // Front face emblem
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(vertAngle);
  ctx.scale(scale, Math.cos(horizAngle)*0.8+0.2);

  // Check if front or back should be shown based on angle
  const showFront = Math.abs(Math.sin(vertAngle)) < 0.8 && Math.cos(horizAngle) > 0;
  const showBack = Math.abs(Math.sin(vertAngle)) < 0.8 && Math.cos(horizAngle) < 0;

  if (showFront || (Math.abs(Math.sin(vertAngle)) >= 0.8 && Math.cos(horizAngle) >= 0)) {
    drawFrontFace(ctx, radius, vertAngle);
  } else {
    drawBackFace(ctx, radius, vertAngle);
  }

  ctx.restore();
}

function drawFrontFace(ctx, radius, angle) {
  ctx.save();
  const alpha = Math.cos(angle) * 0.6;
  ctx.globalAlpha = Math.max(0.1, Math.abs(alpha));

  // Embossed WTM emblem
  ctx.fillStyle = '#c99a27';
  ctx.font = `${radius*0.5}px Arial`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('WT', -radius*0.25, -radius*0.1);
  ctx.fillText('M', 0, radius*0.1);

  ctx.globalAlpha = 1;
  ctx.restore();
}

function drawBackFace(ctx, radius, angle) {
  ctx.save();
  const alpha = Math.cos(angle) * 0.6;
  ctx.globalAlpha = Math.max(0.1, Math.abs(alpha));

  ctx.fillStyle = '#a3d9a3';
  ctx.font = `${radius*0.3}px Arial`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('10,000', 0, -radius*0.1);
  ctx.font = `${radius*0.2}px Arial`;
  ctx.fillText('TOKENS', 0, radius*0.1);

  ctx.globalAlpha = 1;
  ctx.restore();
}

function animate(time) {
  if (!animId) animId = time;
  const elapsed = time - animId;
  const t = (elapsed % 6000) / 6000; // 6 second loop
  drawCoin(ctx, t);
  requestAnimationFrame(animate);
}

function startAnimation() {
  if (!paused && !animId) {
    requestAnimationFrame(animate);
  }
}

// Expose required API
window.demo = {
  canvas: canvas,
  setTime: function(t) {
    // Synchronously render exactly frame at time t
    paused = true;
    drawCoin(ctx, t);
  },
  pause: function() {
    paused = true;
    // Cancel any ongoing animation
  }
};

// Start auto-animation unless paused
startAnimation();

// ===== Edition Canvas Rendering =====
const editions = document.querySelectorAll('.edition-canvas');

function drawEdition(canvasEl, type) {
  const ctx = canvasEl.getContext('2d');
  const size = canvasEl.width;
  const cx = size / 2;
  const cy = size / 2;
  const radius = size * 0.45;

  ctx.clearRect(0, 0, size, size);

  // Base color by type
  let baseColor, highlightColor, textColor;
  switch(type) {
    case 'bronze':
      baseColor = '#cd7f32';
      highlightColor = '#f5deb3';
      textColor = '#fff';
      break;
    case 'silver':
      baseColor = '#c0c0c0';
      highlightColor = '#ffffff';
      textColor = '#000';
      break;
    case 'gold':
      baseColor = '#ffd700';
      highlightColor = '#ffffe0';
      textColor = '#000';
      break;
    case 'black':
      baseColor = '#0a0a1a';
      highlightColor = '#4b0082';
      textColor = '#fff';
      break;
  }

  // Metallic radial gradient
  const grad = ctx.createRadialGradient(cx - radius*0.2, cy - radius*0.2, radius*0.1, cx, cy, radius);
  grad.addColorStop(0, highlightColor);
  grad.addColorStop(0.5, baseColor);
  grad.addColorStop(1, '#555');

  // Draw coin body
  ctx.beginPath();
  ctx.arc(cx, cy, radius, 0, Math.PI * 2);
  ctx.fillStyle = grad;
  ctx.fill();

  // Specular highlight
  ctx.beginPath();
  ctx.ellipse(cx - radius*0.2, cy - radius*0.3, radius*0.25, radius*0.08, -0.3, 0, Math.PI*2);
  ctx.fillStyle = 'rgba(255,255,255,0.6)';
  ctx.fill();

  // Reeded edge
  ctx.strokeStyle = '#aaa';
  ctx.lineWidth = radius * 0.03;
  for (let i = 0; i < 40; i++) {
    ctx.beginPath();
    ctx.arc(cx, cy, radius + radius*0.01, (i/40)*2*Math.PI, (i/40)*2*Math.PI + 0.05);
    ctx.stroke();
  }

  // Denomination/emblem text
  ctx.fillStyle = textColor;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';

  if(type === 'gold') {
    ctx.font = `${radius*0.5}px Arial`;
    ctx.fillText('★', cx, cy - radius*0.1);
    ctx.font = `${radius*0.2}px Arial`;
    ctx.fillText('SOLD OUT', cx, cy + radius*0.15);
  } else if(type === 'black') {
    ctx.font = `${radius*0.4}px Arial`;
    ctx.fillText('✦', cx, cy - radius*0.1);
    ctx.font = `${radius*0.18}px Arial`;
    ctx.fillText('NEXT', cx, cy + radius*0.1);
    ctx.font = `${radius*0.15}px Arial`;
    ctx.fillText('SPRING', cx, cy + radius*0.25);
  } else {
    ctx.font = `${radius*0.4}px Arial`;
    ctx.fillText(type === 'bronze' ? '🥉' : '🥈', cx, cy - radius*0.05);
    ctx.font = `${radius*0.2}px Arial`;
    ctx.fillText(type.toUpperCase(), cx, cy + radius*0.15);
  }
}

editions.forEach((el, i) => {
  const types = ['bronze', 'silver', 'gold', 'black'];
  el.width = 180;
  el.height = 180;
  drawEdition(el, types[i]);
});

// Handle window resize
window.addEventListener('resize', () => {
  resize();
  if (!paused) {
    startAnimation();
  }
});
</script>

</body>
</html>
